def get_tr(key, en, lang):
    if key in T and lang in T[key]:
        return T[key][lang]
    if en in S and lang in S[en]:
        return S[en][lang]
    return en

def main():
    data = json.loads(TRANS.read_text(encoding='utf-8'))
    added = 0
    for lang in LANGS:
        if lang not in data:
            data[lang] = {}
        for key, en in ALL_KEYS.items():
            if key not in data[lang]:
                data[lang][key] = get_tr(key, en, lang)
                added += 1
    TRANS.write_text(json.dumps(data, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
    print(f'Added {added} per-tool translations across {len(LANGS)} languages')

if __name__ == '__main__':
    main()
